</form></div></div>
<style>.protection-choice{cursor:pointer;transition:border-color .15s,box-shadow .15s}.protection-choice:has(input:checked){border-color:var(--bs-primary)!important;box-shadow:0 0 0 .2rem rgba(var(--bs-primary-rgb),.2);background:rgba(var(--bs-primary-rgb),.04)}.sk-symbol{font:700 1.8rem/1 Arial,sans-serif;min-width:3rem;color:var(--bs-emphasis-color)}.protection-plug-image{width:100%;height:86px;object-fit:contain;background:#fff}</style>
<script>
(() => {
  const date = document.querySelector('[name="test_date"]');
  const interval = document.getElementById('interval_days');
  const next = document.getElementById('next_due_date');
  if (!date || !interval || !next) return;
  const update = () => { if (!date.value) return; const d = new Date(date.value + 'T12:00:00'); d.setDate(d.getDate() + Number(interval.value || 365)); next.value = d.toISOString().slice(0, 10); };
  interval.addEventListener('change', update); date.addEventListener('change', update);
})();
</script>
